INSERT INTO constraints (id,name,description,severity,created_at,updated_at) VALUES ('c78a0035-d679-42d8-81a8-346287c64a4b','Knee Injury','Avoid high-impact lower-body exercises','high','2023-01-09 04:13:00','2023-02-08 04:13:00');
